164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        validateRequiredFields(ownerFieldsDto);
166	        LocalDate registrationDate = toBusinessDay(
167	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
168	        rejectDailyLimitReached(registrationDate);
169	        HttpHeaders headers = new HttpHeaders();
170	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
171	        String address = normalizeAddress(ownerFieldsDto.getAddress());
172	        owner.setAddress(address);
173	        rejectCityAtCapacity(owner.getCity());
174	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
175	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
176	        } else {
177	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
178	        }
179	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
180	        rejectDuplicateTelephone(telephone);
181	        owner.setTelephone(telephone);
182	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
183	        owner.setRegistrationDate(registrationDate);
184	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
185	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
186	        this.clinicService.saveOwner(owner);
187	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
188	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
189	        applyHouseholdSize(owner);
190	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
191	        applyBulkSignupWarning(ownerDto);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
