291	    /**
292	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
293	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
294	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
295	     *
296	     * @param ownerFieldsDto the submitted owner fields
297	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
298	     *                                     name of every offending field
299	     */
300	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
301	        List<String> missingFields = new ArrayList<>();
302	        if (isBlank(ownerFieldsDto.getFirstName())) {
303	            missingFields.add("firstName");
304	        }
305	        if (isBlank(ownerFieldsDto.getLastName())) {
306	            missingFields.add("lastName");
307	        }
308	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
309	            missingFields.add("address");
310	        }
311	        if (isBlank(ownerFieldsDto.getCity())) {
312	            missingFields.add("city");
313	        }
314	        if (isBlank(ownerFieldsDto.getTelephone())) {
315	            missingFields.add("telephone");
316	        }
317	        if (!missingFields.isEmpty()) {
318	            throw new InvalidOwnerFieldsException(missingFields);
319	        }
320	    }
321	
322	    private boolean isBlank(String value) {
323	        return value == null || value.isBlank();
324	    }
