371	    /**
372	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
373	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
374	     * returned value is that address lower-cased.
375	     *
376	     * @param email the raw email value submitted by the client, or {@code null} if omitted
377	     * @return the lower-cased email, or {@code null} if none was supplied
378	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
379	     *                                     yielding a 400 response
380	     */
381	    private String normalizeEmail(String email) {
382	        if (email == null) {
383	            return null;
384	        }
385	        if (!EMAIL_PATTERN.matcher(email).matches()) {
386	            throw new InvalidOwnerFieldsException(List.of("email"));
387	        }
388	        return email.toLowerCase(Locale.ROOT);
389	    }
