391	    /**
392	     * Counts the existing owners that, before this create, already share the given first name and
393	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
394	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
395	     * been saved yet, so it is never included in the count.
396	     *
397	     * @param firstName the first name of the owner being created
398	     * @param lastName  the last name of the owner being created
399	     * @return the number of existing owners sharing both names
400	     */
401	    private int countNamesakes(String firstName, String lastName) {
402	        String normalizedFirstName = normalizeForComparison(firstName);
403	        String normalizedLastName = normalizeForComparison(lastName);
404	        return (int) this.clinicService.findAllOwners().stream()
405	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
406	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
407	            .count();
408	    }
