410	    /**
411	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
412	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
413	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
414	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
415	     *
416	     * @param city     the owner's city
417	     * @param lastName the owner's last name
418	     * @return the formatted customer code
419	     */
420	    private String generateCustomerCode(String city, String lastName) {
421	        String city3 = first3Letters(city);
422	        String last3 = first3Letters(lastName);
423	        int sequence = countOwnersInCity(city) + 1;
424	        return String.format("%s-%s-%04d", city3, last3, sequence);
425	    }
426	
427	    /**
428	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
429	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
430	     *
431	     * @param value the value to abbreviate
432	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
433	     */
434	    private String first3Letters(String value) {
435	        String letters = value.replaceAll("[^\\p{L}]", "");
436	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
437	    }
