455	    /**
456	     * Rejects creation of an owner whose city already contains the maximum number of owners
457	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
458	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
459	     *
460	     * @param city the city of the owner being created
461	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
462	     *                                      owners, yielding a 409 Conflict response
463	     */
464	    private void rejectCityAtCapacity(String city) {
465	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
466	            throw new OwnerCityAtCapacityException(city);
467	        }
468	    }
