534	    /**
535	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
536	     * telephones are converted to E.164 here as well so the comparison is independent of the format
537	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
538	     * ignored rather than matched.
539	     *
540	     * @param telephone the E.164 telephone of the owner being created
541	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
542	     *                                          yielding a 409 Conflict response
543	     */
544	    private void rejectDuplicateTelephone(String telephone) {
545	        boolean inUse = this.clinicService.findAllOwners().stream()
546	            .map(Owner::getTelephone)
547	            .map(this::toE164)
548	            .anyMatch(telephone::equals);
549	        if (inUse) {
550	            throw new DuplicateOwnerTelephoneException(telephone);
551	        }
552	    }
553	
554	    /**
555	     * Rejects creation of an owner whose last name and address both match an existing owner's,
556	     * which marks them as belonging to the same household. Both the last name and the address are
557	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
558	     * that differ only in letter case or spacing are still treated as a match.
559	     *
560	     * @param lastName the last name of the owner being created
561	     * @param address  the address of the owner being created
562	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
563	     *                                          address, yielding a 409 Conflict response
564	     */
565	    private void rejectDuplicateHousehold(String lastName, String address) {
566	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
567	            throw new DuplicateOwnerHouseholdException(lastName, address);
568	        }
569	    }
570	
571	    /**
572	     * Finds every existing owner belonging to the household identified by the given last name and
573	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
574	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
575	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
576	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
577	     * and {@link #assignHousehold}.
578	     *
579	     * @param lastName the last name of the owner being created
580	     * @param address  the address of the owner being created
581	     * @return the existing owners in that household, or an empty list if there are none
582	     */
583	    private List<Owner> findHouseholdMembers(String lastName, String address) {
584	        String normalizedLastName = normalizeForComparison(lastName);
585	        String normalizedAddress = normalizeAddress(address);
586	        return this.clinicService.findAllOwners().stream()
587	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
588	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
589	            .toList();
590	    }
591	
592	    /**
593	     * Enrolls a newly created owner into the household of any existing owner that shares its last
594	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
595	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
596	     * whitespace. When at least one such owner already exists, every member of the household — the
597	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
598	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
599	     * and address is created and back-filled onto the existing members. When no owner yet lives at
600	     * that address under the same last name no identifier is assigned and the owner is created alone.
601	     *
602	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
603	     * @param lastName the last name of the owner being created
604	     * @param address  the address of the owner being created
605	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
606	     */
607	    /**
608	     * Populates an owner's transient {@code householdSize} with the number of owners currently
609	     * sharing its {@code householdId} (itself included), so the membership tier computed when the
610	     * response is produced reflects the household's current size. An owner with no {@code householdId}
611	     * belongs to no shared household and is left with a size of zero.
612	     *
613	     * @param owner the owner whose household size is being populated
614	     */
615	    private void applyHouseholdSize(Owner owner) {
616	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()));
617	    }
618	
619	    /**
620	     * Counts the owners that share the given {@code householdId}. Returns zero when the identifier is
621	     * absent, so an owner that belongs to no shared household is never treated as having members.
622	     *
623	     * @param householdId the shared household identifier, possibly {@code null}
624	     * @return the number of owners carrying that household id
625	     */
626	    private int countHouseholdMembers(String householdId) {
627	        if (householdId == null || householdId.isBlank()) {
628	            return 0;
629	        }
630	        return (int) this.clinicService.findAllOwners().stream()
631	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
632	            .count();
633	    }
634	
635	    private String assignHousehold(Owner newOwner, String lastName, String address) {
636	        List<Owner> members = findHouseholdMembers(lastName, address);
637	        if (members.isEmpty()) {
638	            return null;
639	        }
640	        String householdId = members.stream()
641	            .map(Owner::getHouseholdId)
642	            .filter(existing -> existing != null && !existing.isBlank())
643	            .findFirst()
644	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
645	        for (Owner member : members) {
646	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
647	                member.setHouseholdId(householdId);
648	                this.clinicService.saveOwner(member);
649	            }
650	        }
651	        newOwner.setHouseholdId(householdId);
652	        return householdId;
653	    }
654	
655	    /**
656	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
657	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
658	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
659	     * same identifier, so members of one household share a single value.
660	     *
661	     * @param normalizedLastName the household's last name, already normalized for comparison
662	     * @param normalizedAddress  the household's address, already normalized for comparison
663	     * @return the derived household identifier
664	     */
665	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
666	        try {
667	            byte[] digest = MessageDigest.getInstance("SHA-256")
668	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
669	            StringBuilder hex = new StringBuilder(digest.length * 2);
670	            for (byte b : digest) {
671	                hex.append(String.format("%02x", b));
672	            }
673	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
674	        } catch (NoSuchAlgorithmException e) {
675	            throw new IllegalStateException("SHA-256 algorithm not available", e);
676	        }
677	    }
678	
679	    /**
680	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
681	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
682	     * the result is lower-cased.
683	     *
684	     * @param value the value to normalize, possibly {@code null}
685	     * @return the normalized value, or an empty string if {@code value} is {@code null}
686	     */
687	    private String normalizeForComparison(String value) {
688	        if (value == null) {
689	            return "";
690	        }
691	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
692	    }
693	
694	    /**
695	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
696	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
697	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
698	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
699	     * This normalized value is what gets stored and returned, and it is the form every address
700	     * comparison (household duplicate detection and the shared household id) uses.
701	     *
702	     * @param address the raw address value submitted by the client, possibly {@code null}
703	     * @return the normalized address, or an empty string if {@code address} is {@code null}
704	     */
705	    private String normalizeAddress(String address) {
706	        if (address == null) {
707	            return "";
708	        }
709	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
710	        if (collapsed.isEmpty()) {
711	            return collapsed;
712	        }
713	        String[] tokens = collapsed.split(" ");
714	        StringBuilder normalized = new StringBuilder(collapsed.length());
715	        for (int i = 0; i < tokens.length; i++) {
716	            if (i > 0) {
717	                normalized.append(' ');
718	            }
719	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
720	        }
721	        return normalized.toString();
722	    }
723	}
